with with_windows as (select *, rank() over (partition by customer_id order by balance desc) balance_rank, row_number() over (partition by account_type order by opened_date, id) row_seq from accounts) select status, case when balance_rank >= 8 then 'PREMIUM' else 'STANDARD' end as balance_rank_tier, sort_array(collect_set(account_type)) as account_type_list, round(avg(row_seq), 2) as avg_row_seq, count(*) filter (where status = 'OPEN') as open_rows, count(case when status = 'CLOSED' then 1 end) as closed_count, sum(case when account_type = 'SAVINGS' then balance else 0 end) as savings_balance, grouping(status) as grouping_level from with_windows group by grouping sets ((status, case when balance_rank >= 8 then 'PREMIUM' else 'STANDARD' end), (status)) having open_rows >= 1 order by closed_count desc nulls first
